import json, html

with open('/app/output/analysis.json') as f:
    R = json.load(f)

# City display order: by listing count descending
CITIES = ['London', 'Paris', 'Rome', 'Bangkok', 'Barcelona', 'Sydney', 'Amsterdam']
CITIES_WITH_PRICE = ['Bangkok', 'London', 'Barcelona', 'Rome', 'Amsterdam']  # have price data
CITIES_NO_PRICE = ['Paris', 'Sydney']

# Color palette
COLORS = {
    'London': '#2563EB',
    'Paris': '#7C3AED',
    'Rome': '#DC2626',
    'Bangkok': '#D97706',
    'Barcelona': '#059669',
    'Sydney': '#0891B2',
    'Amsterdam': '#E11D48',
}
COLORS_LIST = [COLORS[c] for c in CITIES]

def fmt(n, decimals=0):
    if n is None: return 'N/A'
    if decimals == 0:
        return f"{int(round(n)):,}"
    return f"{n:,.{decimals}f}"

def pct(n):
    if n is None: return 'N/A'
    return f"{n:.1f}%"

# --- Build HTML sections ---

def build_kpi_cards():
    cards_data = [
        ("Total Listings", fmt(R['total_listings']), "Across 7 cities"),
        ("Unique Hosts", fmt(R['total_hosts']), f"Across {R['total_cities']} markets"),
        ("Global Median Price", f"${fmt(R['global_price_median'])}", "5 cities with data"),
        ("Entire Home Share", "73.9%", "Global average"),
        ("Data Snapshot", R['scrape_date'], "Inside Airbnb"),
    ]
    cards_html = ""
    gradients = [
        "linear-gradient(135deg, #2563EB, #1D4ED8)",
        "linear-gradient(135deg, #7C3AED, #6D28D9)",
        "linear-gradient(135deg, #059669, #047857)",
        "linear-gradient(135deg, #D97706, #B45309)",
        "linear-gradient(135deg, #64748B, #475569)",
    ]
    for i, (label, value, subtitle) in enumerate(cards_data):
        cards_html += f'''
        <div class="kpi-card" style="background: {gradients[i]};">
            <div class="kpi-label">{label}</div>
            <div class="kpi-value">{value}</div>
            <div class="kpi-sub">{subtitle}</div>
        </div>'''
    return cards_html

def build_market_overview_table():
    rows = ""
    for city in CITIES:
        count = R['city_counts'][city]
        share = round(count / R['total_listings'] * 100, 1)
        eh = R['entire_home_share'].get(city, 'N/A')
        pr = R['room_type_pct'][city].get('Private room', 0)
        prof = R['professional_host_share'].get(city, 'N/A')

        price_info = R['price_by_city'].get(city)
        if price_info:
            med_price = f"${fmt(price_info['median'])}"
            price_n = fmt(price_info['count'])
            price_note = ""
            if city == 'Bangkok':
                med_price = f"฿{fmt(price_info['median'])}"
                price_note = ' <span class="note-badge">THB</span>'
        else:
            med_price = '<span class="na">No data</span>'
            price_n = "0"
            price_note = ""

        rows += f'''<tr>
            <td><span class="city-dot" style="background:{COLORS[city]}"></span>{city}</td>
            <td class="num">{fmt(count)}</td>
            <td class="num">{pct(share)}</td>
            <td class="num">{med_price}{price_note}</td>
            <td class="num">{pct(eh)}</td>
            <td class="num">{pct(pr)}</td>
            <td class="num">{pct(prof)}</td>
        </tr>'''
    return rows

def build_price_table_by_room():
    rows = ""
    room_types = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']
    for city in CITIES_WITH_PRICE:
        currency = "฿" if city == "Bangkok" else "$"
        city_rows = []
        for rt in room_types:
            key = f"{city}|{rt}"
            d = R['price_by_city_room'].get(key)
            if d and d['count'] >= 3:
                city_rows.append(f'''<tr>
                    <td>{rt}</td>
                    <td class="num">{currency}{fmt(d['median'])}</td>
                    <td class="num">{currency}{fmt(d['mean'])}</td>
                    <td class="num">{fmt(d['count'])}</td>
                </tr>''')
        if city_rows:
            rows += f'<tr class="city-header-row"><td colspan="4"><span class="city-dot" style="background:{COLORS[city]}"></span>{city}</td></tr>'
            rows += ''.join(city_rows)
    return rows

# Build the full HTML
report_html = f'''<!DOCTYPE html>
