            x: {{ grid: {{ color: '#F1F5F9' }}, ticks: {{ callback: v => (v/1000)+'k' }} }},
            y: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// 2. Room Type Stacked Bar
const roomTypes = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room'];
const roomColors = ['#2563EB', '#7C3AED', '#D97706', '#64748B'];
const roomData = {json.dumps({rt: [R['room_type_pct'][c].get(rt, 0) for c in CITIES] for rt in ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']})};

new Chart(document.getElementById('chartRoomType'), {{
    type: 'bar',
    data: {{
        labels: cityLabels,
        datasets: roomTypes.map((rt, i) => ({{
            label: rt,
            data: roomData[rt],
            backgroundColor: roomColors[i],
            borderRadius: 2,
        }}))
    }},
    options: {{
        responsive: true,
        plugins: {{
            legend: {{ display: true, position: 'top', labels: {{ boxWidth: 14, padding: 16 }} }},
            tooltip: {{ callbacks: {{ label: ctx => ctx.dataset.label + ': ' + ctx.parsed.y.toFixed(1) + '%' }} }}
        }},
        scales: {{
            x: {{ stacked: true, grid: {{ display: false }} }},
            y: {{ stacked: true, max: 100, ticks: {{ callback: v => v + '%' }}, grid: {{ color: '#F1F5F9' }} }}
        }}
    }}
}});

// 3. Median Price (USD cities only)
